tests.code:
def F(x, y):
    return (x * y, x + 3 * y)
h = 1e-6
for (x, y) in [(-1, 4), (0.5, -2)]:
    J = jacobian(x, y)
    for j, (dx, dy) in enumerate([(h, 0), (0, h)]):
        a, b = F(x + dx, y + dy), F(x - dx, y - dy)
        for i in range(2):
            num = (a[i] - b[i]) / (2 * h)
            assert abs(J[i][j] - num) < 1e-6, f'at ({x}, {y}) entry [{i}][{j}] should be about {num:.4f}, got {J[i][j]}'

